 const [profileBusy,setProfileBusy]=useState(false);
 useEffect(()=>{
   if(!supabase)return;
   supabase.auth.getSession().then(({data})=>setAuthSession(data.session));
   const {data:{subscription}}=supabase.auth.onAuthStateChange((_event,session)=>setAuthSession(session));
   return ()=>subscription.unsubscribe();
 },[]);
 const openAuth=(mode='signup')=>{setAuthMode(mode);setAuthMessage('');setAuthModal(true)};
 const submitAuth=async(e)=>{
   e.preventDefault(); if(!supabase){setAuthMessage('اتصال Supabase تنظیم نشده است.');return}
   if(authMode==='signup'){
     if(!authName.trim()||!authUsername.trim()||!authEmail.includes('@')||authPassword.length<8||authPassword!==authPassword2){setAuthMessage('اطلاعات را کامل کن؛ رمز حداقل ۸ نویسه و تکرار آن باید یکسان باشد.');return}
   } else if(!authEmail.includes('@')||!authPassword){setAuthMessage('ایمیل و رمز عبور را وارد کن.');return}
   setAuthBusy(true);setAuthMessage('');
   try{
     if(authMode==='signup'){
       const {data,error}=await supabase.auth.signUp({email:authEmail.trim(),password:authPassword,options:{data:{full_name:authName.trim(),username:authUsername.trim()}}});
       if(error)throw error;
       if(data.session){setAuthSession(data.session);setAuthModal(false);setNotice('حساب کاربری ساخته شد.')}
       else setAuthMessage('ثبت‌نام انجام شد. ایمیل خودت را برای تأیید حساب بررسی کن؛ سپس وارد شو.');
     }else{
       const {data,error}=await supabase.auth.signInWithPassword({email:authEmail.trim(),password:authPassword});
       if(error)throw error;
       setAuthSession(data.session);setAuthModal(false);setNotice('با موفقیت وارد شدی.');
     }
   }catch(err){setAuthMessage(err.message||'عملیات ناموفق بود.')}
   finally{setAuthBusy(false)}
 };
 const resetAuthPassword=async()=>{
   if(!supabase||!authEmail.includes('@')){setAuthMessage('ابتدا ایمیل معتبر را وارد کن.');return}
   setAuthBusy(true);const {error}=await supabase.auth.resetPasswordForEmail(authEmail.trim(),{redirectTo:window.location.origin});
   setAuthBusy(false);setAuthMessage(error?error.message:'لینک بازیابی رمز برای ایمیلت ارسال شد.');
 };
 const signOutCustomer=async()=>{if(supabase)await supabase.auth.signOut();setAuthSession(null);setNotice('از حساب کاربری خارج شدی.')};
 const saveManagerProfile=()=>{
   if(!currentManager)return;
   if(!profileName.trim()||!profileUsername.trim()){setNotice('نام و نام کاربری را وارد کن.');return}
   if(currentManager.role==='owner'){setNotice('حساب مدیر اصلی این نسخه آزمایشی ثابت است؛ برای تغییر امن مدیر اصلی باید ورود مدیر به Supabase Auth و نقش سمت سرور منتقل شود.');return}
   if(profileNewPassword&&profileNewPassword.length<8){setNotice('رمز جدید باید حداقل ۸ نویسه باشد.');return}
   const updated={...currentManager,name:profileName.trim(),username:profileUsername.trim(),...(profileNewPassword?{password:profileNewPassword}:{})};
   const next=managers.map(m=>m.id===currentManager.id?updated:m);
   saveManagers(next);setCurrentManager(updated);setProfileNewPassword('');setNotice('اطلاعات حساب مدیر به‌روزرسانی شد.');
 };
 const [products,setProducts]=useState(()=>{try{return JSON.parse(localStorage.getItem('fasterdesign_products'))||initialProducts}catch{return initialProducts}});
