 const [category,setCategory]=useState('همه محصولات'); const [query,setQuery]=useState(''); const [sort,setSort]=useState('featured'); const [cart,setCart]=useState([]); const [liked,setLiked]=useState([]); const [mobileMenu,setMobileMenu]=useState(false); const [notice,setNotice]=useState(''); const [selected,setSelected]=useState(null); const [adminOpen,setAdminOpen]=useState(false); const [adminTab,setAdminTab]=useState('overview'); const [adminAuthed,setAdminAuthed]=useState(false); const [adminPass,setAdminPass]=useState(''); const [adminError,setAdminError]=useState(''); const [editProduct,setEditProduct]=useState(null); const [newProduct,setNewProduct]=useState(false); const [newProductFile,setNewProductFile]=useState(null); const [newProductPreview,setNewProductPreview]=useState(null); const [loginUser,setLoginUser]=useState('admin'); const [currentManager,setCurrentManager]=useState(null); const [managerName,setManagerName]=useState(''); const [managerUsername,setManagerUsername]=useState(''); const [managerPassword,setManagerPassword]=useState(''); const [managerPermissions,setManagerPermissions]=useState(['products','orders']); const [managers,setManagers]=useState(()=>{try{return JSON.parse(localStorage.getItem('fasterdesign_managers'))||[]}catch{return []}}); const [customerEmail,setCustomerEmail]=useState(''); const [library,setLibrary]=useState(()=>{try{return JSON.parse(localStorage.getItem('fasterdesign_library'))||[]}catch{return []}}); const [maintenance,setMaintenance]=useState(()=>localStorage.getItem('fasterdesign_maintenance')==='true'); const [discount,setDiscount]=useState(()=>localStorage.getItem('fasterdesign_discount')||'10'); const [supabaseCheck,setSupabaseCheck]=useState({loading:false,result:null}); const runSupabaseCheck=async()=>{setSupabaseCheck({loading:true,result:null});try{const result=await checkSupabaseConnection();setSupabaseCheck({loading:false,result})}catch(error){setSupabaseCheck({loading:false,result:{ok:false,message:error?.message||'بررسی اتصال ناموفق بود.'}})}};
