 const [ticketEmail,setTicketEmail]=useState(''); const [ticketSubject,setTicketSubject]=useState(''); const [ticketBody,setTicketBody]=useState('');
 const [verifiedEmailInput,setVerifiedEmailInput]=useState(''); const [replyDrafts,setReplyDrafts]=useState({});
 const [reviewName,setReviewName]=useState(''); const [reviewEmail,setReviewEmail]=useState(''); const [reviewRating,setReviewRating]=useState(5); const [reviewBody,setReviewBody]=useState('');
 const [supportPanel,setSupportPanel]=useState(''); const [chatbotEnabled,setChatbotEnabled]=useState(()=>localStorage.getItem('fasterdesign_chatbot_enabled')!=='false'); const [chatOpen,setChatOpen]=useState(false); const [chatInput,setChatInput]=useState(''); const [chatHistory,setChatHistory]=useState([{from:'bot',text:'سلام! من راهنمای Faster Desgin هستم. درباره خرید، فایل‌ها، سفارش‌ها یا پشتیبانی سؤال بپرس.'}]);
 const saveTickets=(v)=>{setTickets(v);localStorage.setItem('fasterdesign_tickets',JSON.stringify(v))};
 const saveReviews=(v)=>{setReviews(v);localStorage.setItem('fasterdesign_reviews',JSON.stringify(v))};
 const saveVerified=(v)=>{setVerifiedUsers(v);localStorage.setItem('fasterdesign_verified_users',JSON.stringify(v))};
 const sendTicket=(e)=>{e.preventDefault();if(!ticketEmail.includes('@')||!ticketSubject.trim()||!ticketBody.trim()){setNotice('ایمیل معتبر، موضوع و متن تیکت را کامل کن.');return}saveTickets([{id:'T-'+Date.now().toString().slice(-6),email:ticketEmail.trim(),subject:ticketSubject.trim(),body:ticketBody.trim(),status:'باز',createdAt:new Date().toLocaleString('fa-IR'),replies:[]},...tickets]);setTicketSubject('');setTicketBody('');setNotice('تیکت برای مدیران ارسال شد. شماره تیکت را نگه دار.')};
 const sendReview=(e)=>{e.preventDefault();if(!reviewName.trim()||!reviewEmail.includes('@')||!reviewBody.trim()){setNotice('نام، ایمیل معتبر و متن نظر را وارد کن.');return}saveReviews([{id:Date.now(),name:reviewName.trim(),email:reviewEmail.trim(),rating:reviewRating,body:reviewBody.trim(),date:new Date().toLocaleDateString('fa-IR'),approved:false},...reviews]);setReviewBody('');setNotice('نظر ثبت شد و پس از بررسی مدیر نمایش داده می‌شود.')};
 const answerTicket=(ticketId,body)=>{if(!body?.trim())return;saveTickets(tickets.map(t=>t.id===ticketId?{...t,status:'پاسخ داده شد',replies:[...(t.replies||[]),{from:'admin',name:currentManager?.name||'مدیر',body:body.trim(),date:new Date().toLocaleString('fa-IR') }]}:t));setReplyDrafts(v=>({...v,[ticketId]:''}));setNotice('پاسخ تیکت ثبت شد.')};
 const sendChat=(e)=>{e?.preventDefault?.();const q=chatInput.trim();if(!q)return;let answer='برای پیگیری سفارش، ایمیلی که هنگام ثبت سفارش وارد کردی را نگه دار و از بخش تیکت‌ها برای مدیریت پیام بفرست.';const lower=q.toLowerCase();if(/خرید|پرداخت|سفارش/.test(lower))answer='برای خرید، محصول را به سبد اضافه کن و ایمیلت را وارد کن. سفارش‌های این نسخه آزمایشی ابتدا منتظر تأیید مدیر می‌مانند و درگاه واقعی متصل نیست.';else if(/دانلود|فایل/.test(lower))answer='دسترسی فایل پس از تأیید سفارش توسط مدیر در کتابخانه آزمایشی فعال می‌شود. اگر فایل نمایش داده نشد، یک تیکت پشتیبانی ثبت کن.';else if(/تیکت|پشتیبانی|مدیر/.test(lower))answer='از دکمه شناور «تیکت پشتیبانی» استفاده کن، ایمیل، موضوع و متن را وارد کن. مدیر می‌تواند از پنل به تیکت پاسخ بدهد.';else if(/سلام/.test(lower))answer='سلام! خوش آمدی. درباره خرید، دانلود فایل یا پشتیبانی هر سؤالی داری بپرس.';setChatHistory(h=>[...h,{from:'user',text:q},{from:'bot',text:answer}]);setChatInput('')};
