 const openAdmin=()=>{setAdminOpen(true);setAdminError('')}
 const adminLogin=()=>{const root={id:'root',username:'admin',name:'مدیر اصلی',password:'2468',role:'owner',permissions:['all']};const found=loginUser==='admin'&&adminPass==='2468'?root:managers.find(m=>m.username===loginUser&&m.password===adminPass);if(found){setCurrentManager(found);setProfileName(found.name||'');setProfileUsername(found.username||'');setAdminAuthed(true);setAdminError('');if(found.role!=='owner'&&!found.permissions?.includes(adminTab))setAdminTab(found.permissions?.[0]||'overview')}else setAdminError('نام کاربری یا رمز عبور اشتباه است.')}
