 const approveOrder=(orderId,approved)=>{const order=orders.find(o=>o.id===orderId);if(!order)return;const status=approved?'تأیید شد — دسترسی فعال':'رد شده';saveOrders(orders.map(o=>o.id===orderId?{...o,status,reviewedAt:new Date().toLocaleString('fa-IR')}:o));if(approved){const already=library.some(x=>x.orderId===order.id);if(!already)saveLibrary([...library,...order.items.map(item=>({...item,orderId:order.id,email:order.email}))]);setNotice('سفارش تأیید شد و به کتابخانه آزمایشی اضافه شد.')}else setNotice('درخواست سفارش رد شد.')}
 const attachPreview=(file,productId=null,onNew=null)=>{if(!file)return;if(file.size>2*1024*1024){setNotice('پیش‌نمایش باید کمتر از ۲ مگابایت باشد.');return}if(!file.type.startsWith('image/')&&!file.type.startsWith('video/')){setNotice('برای پیش‌نمایش فقط تصویر یا ویدئو انتخاب کن.');return}const reader=new FileReader();reader.onload=()=>{const asset={name:file.name,size:file.size,type:file.type,data:reader.result};if(productId!==null)updateProduct(productId,'previewMedia',asset);else if(onNew)onNew(asset);setNotice('پیش‌نمایش محصول ذخیره شد.')} ;reader.onerror=()=>setNotice('خواندن پیش‌نمایش ناموفق بود.');reader.readAsDataURL(file)}
 const updateProduct=(id,key,value)=>saveProducts(products.map(p=>p.id===id?{...p,[key]:value}:p))
 const attachProductFile=(file, productId=null, onNew=null)=>{if(!file)return;if(file.size>2*1024*1024){setNotice('برای نسخه نمایشی فایل باید کمتر از ۲ مگابایت باشد. برای فایل‌های بزرگ فضای ذخیره‌سازی سرور لازم است.');return}const reader=new FileReader();reader.onload=()=>{const asset={name:file.name,size:file.size,type:file.type||'application/octet-stream',data:reader.result};if(productId!==null){updateProduct(productId,'downloadableFile',asset);setNotice('فایل دانلود محصول ذخیره شد.')}else if(onNew){onNew(asset)}};reader.onerror=()=>setNotice('خواندن فایل ناموفق بود. دوباره امتحان کن.');reader.readAsDataURL(file)}
